def drain(collector) do
  ordered = Agent.get(collector, &Enum.reverse/1)
  logs = for %{"method" => "notifications/message"} = n <- Enum.reverse(ordered), do: n

  {drained, []} =
    Enum.map_reduce(ordered, logs, fn
      %{"method" => "notifications/message"}, [log | rest] -> {log, rest}
      n, rest -> {n, rest}
    end)

  drained
end

{:error, {:malformed_request, id, error}} ->
  response = %{"jsonrpc" => "2.0", "id" => id, "error" => Map.from_struct(error)}
  state.transport_module.send_message(state.transport_pid, response)
  {:noreply, state}

{:error, error} ->
  Logger.warning("MCP.Server.Connection: failed to decode message: #{inspect(error)}")

